using System;
using UnityEngine;

namespace FerrySim.Audio.Clips
{
	/// <summary>Generated by AudioCatalogBuilder so WAV assets are referenced in shipping players.</summary>
	public sealed class AudioClipCatalog : ScriptableObject
	{
		public TextAsset manifest;
		public Entry[] clips = Array.Empty<Entry>();
		[Serializable] public sealed class Entry
		{
			public string id;
			public AudioClip clip;
		}
	}
}
